(function () {
  'use strict';
  // Launch operations v234 view (owner ruling 12 Nov 2026: the ten-rank ladder, slots 0-9, no Stewart).
  // Presentation and fail-closed admission only. It reads the admitted /api/admin/launch-operations page,
  // never fetches, stores or selects anything, and gives the website no in-game authority: officers
  // choose and confirm every rank step in the addon. The pinned values below are the producer's
  // worker/src/native-rank-constants.ts (generated by tools/build-native-ranks.py); any other
  // protocol, profile, digest, names, status or row shape is held instead of reinterpreted.
  const PROTOCOL = 'officer-operations-v234', LEGACY = 'officer-operations-v233';
  const PROFILE = 'olympus-prime-directive-20261112-v1';
  const DIGEST = '84be4203598ba7bf6c506547c681ba6b7338414ae00add5d64055eeeea98bd29';
  const NAMES = Object.freeze(['Guild Master', 'High Council', 'Officer', 'Officer Alt', 'Raid Leader', 'Veteran', 'Raider', 'Member', 'Alt', 'Initiate']);
  // The only two final targets the producer recommends (launch-operations229.ts:103-104).
  const TARGETS = Object.freeze({'knight-veteran': {slot: 5, name: 'Veteran', from: [6, 9]}, 'verified-initiate': {slot: 7, name: 'Member', from: [9, 9]}});
  const ROW_KEYS = 'currentSlot,guid,name,reason,targetName,targetSlot';
  const GUID = /^Player-\d{1,6}-[0-9A-Fa-f]{4,16}$/;
  const plain = value => !!value && typeof value === 'object' && !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype;
  const text = (value, max) => typeof value === 'string' && value.length > 0 && value.length <= max && !/[\x00-\x1f\x7f]/.test(value);

  const VERDICTS = Object.freeze({
    'legacy-protocol': 'This reply uses the rank ladder from before 12 November. Its slot numbers no longer match the guild’s ranks, so nothing from it is shown.',
    'unknown-protocol': 'This reply is in a format this page does not recognise, so nothing from it is shown.',
    'unknown-status': 'This reply has a status this page does not recognise, so nothing from it is shown.',
    'malformed-rank-table': 'The rank table in this reply is missing or incomplete, so its recommendations are not shown.',
    'unknown-profile': 'This reply names a rank table this page does not recognise, so its recommendations are not shown.',
    'unknown-digest': 'The check value (digest) of the rank table in this reply does not match the 12 November ladder, so its recommendations are not shown.',
    'unknown-rank-names': 'The rank names in this reply do not match the 12 November ladder, so its recommendations are not shown.',
    'unknown-row-shape': 'A row in this reply is not in the expected form, so nothing from it is shown.',
    'rank-table-changed': 'The rank table changed between pages of this scan. Start again from the first page.',
  });
  const HOLDS = Object.freeze({
    'native-unguilded-proof-required': 'No Knight invite is shown until the addon sees in game that the same character is not in a guild.',
    'entitlement-expired': 'The Discord role check is too old to use. Read the page again.',
    'native-snapshot-unavailable': 'There is no complete roster export from the last ten minutes.',
    'native-rank-scheme-unconfirmed': 'The latest roster export does not show the ten ranks of the 12 November ladder, or a member’s rank does not match its slot. Promotions stay held until the in-game ranks match and a new export arrives.',
    'native-identity-ambiguous': 'Two roster rows share a name or character ID, or a row is malformed. Nothing is recommended until a clean export arrives.',
    'flagship-native-scope-unconfirmed': 'The site is not set up to read the OLYMPUS PRIME roster.',
    'directive-rank-policy-held': 'The site’s Discord rank settings do not use the 12 November ladder yet.',
    'native-secret-unconfigured': 'The addon link key is not set up on the site.',
    'selection-source-not-current': 'The addon’s selection is out of date.',
    'selected-target-unavailable': 'A selected character is not on the current roster export.',
    'promotion-actor-unconfirmed': 'The officer making the selection is not confirmed at Raid Leader or above on the roster export.',
    'selected-native-page-ambiguous': 'The selected characters could not each be matched to one roster row.',
    'selection-read-expired': 'The selection window closed before the read finished.',
    'native-snapshot-changed': 'The roster export or the site’s settings changed during the read. Read the page again.',
    'launch-page-verification-changed': 'A member’s link or verification changed during the read. Read the page again.',
    'launch-read-window-exhausted': 'The read ran out of time before every Discord role was checked. Read the page again.',
    'officer-invite-read-deferred': 'The invite list was not read because Discord asked the site to slow down.',
    'discord-rate-limited': 'Discord asked the site to slow down. Wait, then read again.',
    'discord-entitlement-unavailable': 'Some Discord roles could not be read, so those members stay held.',
    'officer-invite-read-held': 'The invite list could not be read, so no invite is shown.',
    'officer-invite-source-held': 'The invite evidence did not come from a current addon check, so no invite is shown.',
    'officer-invite-standing-held': 'An invite candidate’s account standing could not be confirmed, so no invite is shown.',
    'officer-invite-current-policy-held': 'The invite rules changed during the read, so no invite is shown.',
    'officer-invite-read-unknown': 'The invite list could not be confirmed, so no invite is shown.',
  });
  const ROW_HOLDS = Object.freeze({
    'native-rank-unconfirmed': 'Rank does not match its slot in the rank table',
    'pending-verification': 'Verification is still pending',
    'verification-unknown': 'Verification state is unknown',
    'discord-entitlement-unknown': 'Discord roles not checked yet',
    'same-intent-continuation-held': 'The next step of an earlier plan could not be confirmed',
  });
  const holdText = code => Object.hasOwn(HOLDS, code) ? HOLDS[code] : 'Held for a reason this page does not recognise (code ' + String(code).slice(0, 80) + '). Treat it as held and tell the site team.';
  const rowHoldText = code => Object.hasOwn(ROW_HOLDS, code) ? ROW_HOLDS[code] : 'Held (code ' + String(code).slice(0, 80) + ')';

  /** The rank fields are all present and exactly the pinned ladder, all null, or malformed. */
  function rankState(d) {
    const fields = [d.rankProfile, d.rankSchemeDigest, d.rankNames];
    if (fields.every(value => value === null)) return 'none';
    if (fields.some(value => value === null || value === undefined)) return 'malformed-rank-table';
    if (typeof d.rankProfile !== 'string') return 'malformed-rank-table';
    if (typeof d.rankSchemeDigest !== 'string' || !/^[a-f0-9]{64}$/.test(d.rankSchemeDigest)) return 'malformed-rank-table';
    if (!Array.isArray(d.rankNames) || d.rankNames.length !== 10 || Object.keys(d.rankNames).length !== 10 || d.rankNames.some(name => !text(name, 96))) return 'malformed-rank-table';
    if (d.rankProfile !== PROFILE) return 'unknown-profile';
    if (d.rankSchemeDigest !== DIGEST) return 'unknown-digest';
    if (d.rankNames.some((name, i) => name !== NAMES[i])) return 'unknown-rank-names';
    return 'current';
  }
  /** One promotion row exactly as the website page carries it (no intent, no token, no extra key). */
  function promotionShape(r) {
    if (!plain(r) || Object.keys(r).sort().join(',') !== ROW_KEYS || !text(r.name, 96) || typeof r.guid !== 'string' || !GUID.test(r.guid)) return false;
    const target = Object.hasOwn(TARGETS, r.reason) ? TARGETS[r.reason] : null;
    return !!target && Number.isInteger(r.currentSlot) && r.currentSlot >= target.from[0] && r.currentSlot <= target.from[1]
      && r.targetSlot === target.slot && r.targetName === target.name && NAMES[r.targetSlot] === r.targetName;
  }
  /**
   * Admission of one page. `first` is the page this one continues (a cursor read), or null.
   * Returns {ok:true} or {ok:false, code, text}; the caller shows a held notice for a refusal.
   */
  function assess(d, first) {
    const refuse = code => ({ok: false, code, text: VERDICTS[code]});
    if (!plain(d)) return refuse('unknown-protocol');
    if (d.protocol === LEGACY) return refuse('legacy-protocol');
    if (d.protocol !== PROTOCOL) return refuse('unknown-protocol');
    if (!['held', 'ready', 'partial'].includes(d.status)) return refuse('unknown-status');
    const rank = rankState(d);
    if (rank !== 'current' && rank !== 'none') return refuse(rank);
    // A ready or partial page always carries the table it was projected from (launch-operations229.ts:74,84,91).
    if (rank === 'none' && d.status !== 'held') return refuse('malformed-rank-table');
    if (!Array.isArray(d.heldReasons) || d.heldReasons.length > 64 || d.heldReasons.some(code => !text(code, 120))) return refuse('unknown-row-shape');
    if (!Array.isArray(d.promotions) || d.promotions.some(r => !promotionShape(r))) return refuse('unknown-row-shape');
    if (!Array.isArray(d.held) || d.held.some(r => !plain(r) || !text(r.name, 96) || typeof r.guid !== 'string' || !GUID.test(r.guid) || !text(r.reason, 120))) return refuse('unknown-row-shape');
    if (first && (first.rankProfile !== d.rankProfile || first.rankSchemeDigest !== d.rankSchemeDigest
      || JSON.stringify(first.rankNames) !== JSON.stringify(d.rankNames))) return refuse('rank-table-changed');
    return {ok: true};
  }
  /** Every separate in-game step from the current slot to the final target, one slot per confirmed click. */
  function steps(r) {
    const out = [];
    for (let slot = r.currentSlot; slot > r.targetSlot; slot--) out.push({from: slot, to: slot - 1, fromName: NAMES[slot], toName: NAMES[slot - 1]});
    return out;
  }
  const short = digest => digest.slice(0, 8) + '…' + digest.slice(-8);
  const COLUMNS = Object.freeze(['Character', 'Now', 'Final rank', 'In-game steps', 'Evidence']);
  const clicks = n => n === 1 ? '1 confirmed in-game click' : n + ' separate confirmed in-game clicks';

  function heldNotice(verdict, ui) {
    return ui.frame('Recommendations held', null,
      ui.h('p', {'data-launch234-held': verdict.code, text: verdict.text}),
      ui.h('p', {class: 'muted small', text: 'Nothing was selected or sent. Refresh the first page to read it again.'}));
  }
  function holdList(codes, ui) {
    if (!codes.length) return ui.h('p', {class: 'muted small', text: 'No holds on this read.'});
    return ui.h('div', null, ui.h('h3', {text: 'Holds on this read'}),
      ui.h('ul', {class: 'launch234-holds'}, codes.map(code => ui.h('li', {'data-launch234-hold': code, text: holdText(code)}))));
  }
  function rankFrame(d, ui) {
    if (rankState(d) !== 'current') {
      return ui.frame('Rank table in force', null,
        ui.h('p', {'data-launch234-ranks': 'unconfirmed', text: 'The guild’s rank table was not confirmed on this read, so no promotion is recommended.'}));
    }
    const rows = d.rankNames.map((name, slot) => ui.h('tr', null, ui.h('th', {scope: 'row', text: String(slot)}), ui.h('td', {text: name})));
    return ui.frame('Rank table in force', null,
      ui.h('p', {text: 'These are the ten in-game ranks of the latest roster export. They match the ladder set on 12 November, so the slots below are the ones the recommendations use.'}),
      ui.h('div', {class: 'table-wrap launch234-ranks'}, ui.h('table', {'data-launch234-ranks': 'current'},
        ui.h('caption', {class: 'muted small', text: 'Rank names by slot (0 is the highest)'}),
        ui.h('thead', null, ui.h('tr', null, ui.h('th', {scope: 'col', text: 'Slot'}), ui.h('th', {scope: 'col', text: 'Rank'}))),
        ui.h('tbody', null, rows))),
      ui.h('dl', {class: 'launch234-source'},
        ui.h('dt', {text: 'Rank profile'}), ui.h('dd', null, ui.h('code', {text: d.rankProfile})),
        ui.h('dt', {text: 'Digest'}), ui.h('dd', null, ui.h('code', {'data-launch234-digest-short': '', text: short(d.rankSchemeDigest)}),
          ui.h('details', {class: 'launch234-digest'}, ui.h('summary', {text: 'Show the full digest'}), ui.h('code', {'data-launch234-digest': '', text: d.rankSchemeDigest})))),
      ui.h('p', {class: 'muted small', text: 'This page cannot select or promote anyone. Officers choose a character and confirm each rank step in the addon; the website only shows the plan.'}));
  }
  function promotionTable(rows, eligible, ui) {
    const body = rows.map(r => {
      const path = steps(r);
      // Explicit roles keep the table semantics when narrow screens restack the rows as cards (app.css).
      return ui.h('tr', {role: 'row', [eligible ? 'data-launch-promotion229' : 'data-launch-advisory229']: r.guid, 'data-launch234-steps': String(path.length)},
        ui.h('th', {scope: 'row', role: 'rowheader', text: r.name}),
        ui.h('td', {role: 'cell', 'data-label': COLUMNS[1], text: NAMES[r.currentSlot] + ' (slot ' + r.currentSlot + ')'}),
        ui.h('td', {role: 'cell', 'data-label': COLUMNS[2], text: r.targetName + ' (slot ' + r.targetSlot + ')'}),
        ui.h('td', {role: 'cell', 'data-label': COLUMNS[3], class: 'launch234-path'},
          ui.h('ol', null, path.map(step => ui.h('li', {text: step.fromName + ' to ' + step.toName + ' (slot ' + step.to + ')'}))),
          ui.h('span', {class: 'muted small', text: clicks(path.length) + ' remaining'})),
        ui.h('td', {role: 'cell', 'data-label': COLUMNS[4], text: eligible ? 'Role evidence current' : 'Stale advisory · recheck required'}));
    });
    return ui.h('div', {class: 'table-wrap launch234-promotions'}, ui.h('table', {role: 'table'},
      ui.h('thead', {role: 'rowgroup'}, ui.h('tr', {role: 'row'}, COLUMNS.map(label => ui.h('th', {scope: 'col', role: 'columnheader', text: label})))),
      ui.h('tbody', {role: 'rowgroup'}, body.length ? body : ui.h('tr', {role: 'row'}, ui.h('td', {role: 'cell', colspan: '5', class: 'muted', text: 'None on this page.'})))));
  }
  /** The two promotion groups of one examined page, each with its path explained. */
  function promotionGroups(d, eligible, ui) {
    const of = reason => d.promotions.filter(r => r.reason === reason);
    return [
      ui.h('h3', {text: 'Knights to Veteran (slot 5)'}),
      ui.h('p', {class: 'muted small', text: 'A linked Knight below Veteran moves up one rank per click: from Raider it takes one click, from Initiate four.'}),
      promotionTable(of('knight-veteran'), eligible, ui),
      ui.h('h3', {text: 'Verified Initiates to Member (slot 7), by way of Alt'}),
      ui.h('p', {class: 'muted small', text: 'This takes two separate clicks: Initiate to Alt, then Alt to Member. After the first click the character is an Alt and drops off this list; the second click continues the same plan in the addon. An Alt who did not start from this plan is not promoted.'}),
      promotionTable(of('verified-initiate'), eligible, ui),
    ];
  }
  window.OlympusLaunch234 = Object.freeze({PROTOCOL, PROFILE, DIGEST, NAMES, assess, promotionShape, steps, holdText, rowHoldText, heldNotice, holdList, rankFrame, promotionGroups});
}());
